import path from 'path';
import Handlebars from 'handlebars';

export interface PageData {
  title: string;
  date: string;
  tags: string[];
  content: string;
  slug: string;
  layout?: string;
  template?: string;
}

export class TemplateEngine {
  private templatesDir: string;
