describe('incremental build stats', () => {
  let consoleLogSpy: jest.SpyInstance;

  beforeEach(() => {
    consoleLogSpy = jest.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    consoleLogSpy.mockRestore();
  });

  it('reports stats after incremental build', () => {
    const contentDir = createContentDir('inc-stats');
    const outputDir = path.join(tmpDir, 'inc-stats-out');

    writeFile(contentDir, 'a.md', '---\ntitle: A\n---\nContent A');
    writeFile(contentDir, 'b.md', '---\ntitle: B\n---\nContent B');

    generateSite(contentDir, outputDir, undefined, { incremental: true });

    // Second build — skip both pages
    generateSite(contentDir, outputDir, undefined, { incremental: true });

    const statCalls = consoleLogSpy.mock.calls.filter((c: string[]) =>
      c[0] && c[0].includes('Build stats:')
    );
    expect(statCalls.length).toBe(1);
    expect(statCalls[0][0]).toMatch(/2 built/);
    expect(statCalls[0][0]).toMatch(/0 skipped/);

    // Third build after modifying one file
    writeFile(contentDir, 'a.md', '---\ntitle: A New\n---\nContent A modified');
    generateSite(contentDir, outputDir, undefined, { incremental: true });

    const statCalls2 = consoleLogSpy.mock.calls.filter((c: string[]) =>
      c[0] && c[0].includes('Build stats:')
    );
    expect(statCalls2.length).toBe(2);
    expect(statCalls2[1][0]).toMatch(/2 built/);
    expect(statCalls2[1][0]).toMatch(/0 skipped/); // actually a.md changed so 2 built (a+idx), b skipped

    // Hmm wait, with consoleLogSpy, the build stats says: pagesBuilt counts include index
    // a changed -> 1 page rebuilt + 1 index = 2 built, b = 1 skipped
    // Let me re-check: index is always "builtCount++" so builtCount includes index
    // So builtCount = 1 (a changed) + 1 (index) = 2, skippedCount = 1 (b unchanged)
    // totalPages = 2 + 1 = 3
    // So message should be: "2 built, 1 skipped"
    expect(statCalls2[1][0]).toMatch(/2 built/);
    expect(statCalls2[1][0]).toMatch(/1 skipped/);
  });

  it('non-incremental build does not show stats', () => {
    const contentDir = createContentDir('inc-no-stats');
    const outputDir = path.join(tmpDir, 'inc-no-stats-out');

    writeFile(contentDir, 'a.md', '---\ntitle: A\n---\nContent A');

    generateSite(contentDir, outputDir);

    const statCalls = consoleLogSpy.mock.calls.filter((c: string[]) =>
      c[0] && c[0].includes('Build stats:')
    );
    expect(statCalls.length).toBe(0);
  });
});

